/// <summary>
/// Base class for METPricingAttribute table <c>EcoResProductCategory</c>
/// </summary>
internal abstract class METGUPPricingAttributeEcoResProductCategory extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
    /// <summary>
    /// Get table record of ecoresProductCategory
    /// </summary>
    /// <param name="_pricingObject">
    /// The <c>Common</c> object that will be used to get the table record
    /// </param>
    /// <returns><c>EcoResProductCategory</c> object</returns>
    protected EcoResProductCategory getTableRecord(Common _pricingObject)
    {
        EcoResProductCategory ecoResProductCategory;
        SalesLine salesLine = _pricingObject as SalesLine;

        if (salesLine.ItemId)
        {
            InventTable inventTable;
            EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;

            container hierarchyRolesForPricing = GUPCategoryHierarchyLookupHelper::getHierarchyRolesForPricing();

            while select ecoResCategoryHierarchyRole
                join ecoResProductCategory
                    where ecoResProductCategory.CategoryHierarchy == ecoResCategoryHierarchyRole.CategoryHierarchy
                exists join inventTable
                    where inventTable.Product == ecoResProductCategory.Product
                        && inventTable.ItemId == salesLine.ItemId
            {
                int         idx = 0;
                int         len = conLen(hierarchyRolesForPricing);

                // if product category record is under supported category hierarchy roles.
                while (idx < len)
                {
                    idx += 1;

                    EcoResCategoryNamedHierarchyRole tmp = conPeek(hierarchyRolesForPricing, idx);
                    if (tmp == ecoResCategoryHierarchyRole.NamedCategoryHierarchyRole)
                    {
                        return ecoResProductCategory;
                    }
                }
            }
        }

        return ecoResProductCategory;
    }

/// <summary>
/// Get value datasource identifier table string 
/// </summary>
/// <returns>table name string</returns>
public str getQueryBuilderDatasourceIdentifier()
{
    return tableStr(EcoResProductCategory);
}

    /// <summary>
    /// Get value query build datasource object
    /// </summary>
    /// /// <param name="_query">
    /// The <c>Query</c> object that will be used to generate query datasource
    /// </param>
    /// /// <param name="_qbdsMap">
    /// The <c>Map</c> object that will be used to manage categories 
    /// </param>
    /// <returns><c>QueryBuildDataSource</c> object</returns>
    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsEcoResCategory, qbdsRootInventTable;
        QueryBuildDataSource qbdsExistsJoin;

        if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
        {
            qbdsRootInventTable = _qbdsMap.lookup(tableStr(InventTable));
        }
        else
        {
            qbdsRootInventTable = _query.addDataSource(tableNum(InventTable));
            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(InventTable), qbdsRootInventTable);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
        {
            qbdsEcoResCategory = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
        }
        else
        {
            qbdsEcoResCategory = qbdsRootInventTable.addDataSource(tableNum(EcoResProductCategory));
            qbdsEcoResCategory.addLink(fieldNum(InventTable, Product), fieldNum(EcoResProductCategory, Product));
            qbdsEcoResCategory.joinMode(JoinMode::InnerJoin);

            qbdsEcoResCategory = qbdsEcoResCategory.addDataSource(tableNum(EcoResCategory));
            qbdsEcoResCategory.addLink(fieldNum(EcoResProductCategory, Category), fieldNum(EcoResCategory, RecId));
            qbdsEcoResCategory.joinMode(JoinMode::InnerJoin);

            qbdsExistsJoin = qbdsEcoResCategory.addDataSource(tableNum(EcoResCategoryHierarchyRole));
            qbdsExistsJoin.addLink(fieldNum(EcoResCategory, CategoryHierarchy), fieldNum(EcoResCategoryHierarchyRole, CategoryHierarchy));
            qbdsExistsJoin.joinMode(JoinMode::ExistsJoin);

            if (_qbdsMap)
            {
                _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbdsEcoResCategory);
            }
        }

        return qbdsEcoResCategory;
    }

    /// <summary>
    /// Builds pricing object query
    /// </summary>
    /// <param name="_query">
    /// The <c>Query</c> object that the new ranges will be added to.
    /// </param>
    /// <param name="_value">
    /// The <c>anytype</c> object that determines the category.
    /// </param>
    /// <param name="_qdbsMap">
    /// The <c>Map</c> object that is used to identify the query build data source.
    /// </param>
    /// <returns><c>Query</c> object</returns>
    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }

/// <summary>
/// Gets the path of the attribute tables 
/// </summary>
public GUPPricingAttributeTableFieldPath getPath()
{
    return METConstants::pathNotExist;
}

					
    /// <summary>
    /// Get the table name
    /// </summary>
    /// <returns>
    /// Returns a TableName object
    /// </returns>
    public TableName getTableName()
    {
        return tableStr(EcoResProductCategory);
    }
